    "generated_witness", Path("/tmp/audit-work/reconstruction/solution.py")
)


def k_summary(text: str, depth: int = 0) -> bool:
    if not text:
        return depth == 0
    if depth < 0:
        return False
    head, rest = text[0], text[1:]
    if depth == 0 and head != "<":
        return False
    return k_summary(rest, depth + 1 if head == "<" else depth - 1)


